def reverse_only_letters(s):
    chars = list(s)
    left, right = 0, len(chars) - 1

    while left < right:
        while left < right and not chars[left].isalpha():
            left += 1
        while left < right and not chars[right].isalpha():
            right -= 1

        chars[left], chars[right] = chars[right], chars[left]
        left += 1
        right -= 1

    return "".join(chars)

def first_non_repeating_char(s):
    freq = {}

    for ch in s:
        freq[ch] = freq.get(ch, 0) + 1

    for ch in s:
        if freq[ch] == 1:
            return ch

    return None

def move_zeroes(nums):
    write = 0

    for num in nums:
        if num != 0:
            nums[write] = num
            write += 1

    while write < len(nums):
        nums[write] = 0
        write += 1

    return nums

def is_anagram(s, t):
    if len(s) != len(t):
        return False

    freq = {}

    for ch in s:
        freq[ch] = freq.get(ch, 0) + 1

    for ch in t:
        if ch not in freq:
            return False
        freq[ch] -= 1
        if freq[ch] < 0:
            return False

    return True

def two_sum(nums, target):
    seen = {}

    for i, num in enumerate(nums):
        needed = target - num
        if needed in seen:
            return [seen[needed], i]
        seen[num] = i

    return []

def remove_duplicates(nums):
    if not nums:
        return 0

    write = 1

    for read in range(1, len(nums)):
        if nums[read] != nums[read - 1]:
            nums[write] = nums[read]
            write += 1

    return write

def is_palindrome(s):
    left, right = 0, len(s) - 1

    while left < right:
        while left < right and not s[left].isalnum():
            left += 1
        while left < right and not s[right].isalnum():
            right -= 1

        if s[left].lower() != s[right].lower():
            return False

        left += 1
        right -= 1

    return True

def majority_element(nums):
    candidate = None
    count = 0

    for num in nums:
        if count == 0:
            candidate = num

        if num == candidate:
            count += 1
        else:
            count -= 1

    return candidate

def binary_search(nums, target):
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

def merge_sorted_arrays(a, b):
    i, j = 0, 0
    merged = []

    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            merged.append(a[i])
            i += 1
        else:
            merged.append(b[j])
            j += 1

    while i < len(a):
        merged.append(a[i])
        i += 1

    while j < len(b):
        merged.append(b[j])
        j += 1

    return merged

def max_vowels_in_window(s, k):
    vowels = set("aeiouAEIOU")
    current = 0

    for i in range(min(k, len(s))):
        if s[i] in vowels:
            current += 1

    best = current

    for right in range(k, len(s)):
        if s[right - k] in vowels:
            current -= 1
        if s[right] in vowels:
            current += 1
        best = max(best, current)

    return best

def sum_of_digits(n):
    if n < 10:
        return n
    return n % 10 + sum_of_digits(n // 10)

def is_sorted_and_rotated(nums):
    drops = 0
    n = len(nums)

    for i in range(n):
        if nums[i] > nums[(i + 1) % n]:
            drops += 1
            if drops > 1:
                return False

    return True

def assign_cookies(greed, cookies):
    greed.sort()
    cookies.sort()

    i = 0  # child pointer
    j = 0  # cookie pointer

    while i < len(greed) and j < len(cookies):
        if cookies[j] >= greed[i]:
            i += 1
        j += 1

    return i

def frequency_sort(s):
    freq = {}

    for ch in s:
        freq[ch] = freq.get(ch, 0) + 1

    sorted_chars = sorted(freq.items(), key=lambda item: item[1], reverse=True)

    result = []
    for ch, count in sorted_chars:
        result.append(ch * count)

    return "".join(result)

def intersection(nums1, nums2):
    set1 = set(nums1)
    result = set()

    for num in nums2:
        if num in set1:
            result.add(num)

    return list(result)

def length_of_last_word(s):
    i = len(s) - 1

    while i >= 0 and s[i] == " ":
        i -= 1

    length = 0
    while i >= 0 and s[i] != " ":
        length += 1
        i -= 1

    return length
